function d(e){if(e.length<=160)return e;let o=e.slice(0,159);return`${o.slice(0,Math.max(o.lastIndexOf(` `),80)).replace(/[\s,;:.]+$/,``)}\u2026`}var n={hubHeading:`YouTubers on Mastodon: creators to follow, by topic`,hubDescription:`Find YouTube creators who are on Mastodon, by topic: follow their Mastodon accounts and subscribe to their channels, no YouTube account needed.`,hubIntro:[`Many YouTube creators also post on Mastodon. These kits list them by topic, each with their Mastodon account and their YouTube channel, so you can follow one, subscribe to the other, or both.`,`A creator is listed when their YouTube channel and Mastodon account point to each other, they have been active recently, and they meet our listing rules: nothing adult, nothing extremist.`],kitHeading:(e,o)=>`${e} YouTubers on Mastodon: ${o} creators to follow`,kitDescription:(e,o)=>`${o} ${e.toLowerCase()} YouTube creators you can follow on Mastodon, with their channels. Follow or subscribe in Mawkingbird, no YouTube account needed.`,kitIntro:e=>`YouTube creators about ${e.toLowerCase()} who also post on Mastodon. Follow their accounts, subscribe to their channels, or both, in one click with Mawkingbird.`,eyebrow:`YouTubers on Mastodon`,openKit:`Follow and subscribe in Mawkingbird`,noAccount:`No Mastodon account yet? You can still subscribe to the channels and try the kit in your browser.`,openApp:`Open the app`,lastVideo:`Latest video`,videoFeed:`Video feed account`,channel:`YouTube channel`,moreKits:`More YouTuber kits`,allKits:`All YouTuber kits`,creators:e=>`${e} creators`,faqTitle:`Questions`,faq:[{q:`Do I need a YouTube account?`,a:`No. Mawkingbird reads each channel’s public feed, so new videos show up in your subscriptions without signing in to YouTube.`},{q:`Who is listed?`,a:`Creators whose YouTube channel and Mastodon account point to each other, through their profile, their channel or Wikidata, and who posted or uploaded recently. Some entries are accounts that repost a channel’s videos; they are marked as video feed accounts.`},{q:`How do I get listed or removed?`,a:`The kits are refreshed regularly from public profiles. If you would rather not be listed, contact Mawkingbird and you will be left out of future refreshes.`}],contact:`Ask Mawkingbird on Mastodon`,alsoIn:`Also in`};var c={en:n,de:{hubHeading:`YouTuber auf Mastodon: Creator zum Folgen, nach Thema`,hubDescription:`YouTube-Creator auf Mastodon, nach Themen: Folge ihren Mastodon-Konten und abonniere ihre Kanäle – ganz ohne YouTube-Konto.`,hubIntro:[`Viele YouTube-Creator posten auch auf Mastodon. Diese Listen ordnen sie nach Themen, jeweils mit Mastodon-Konto und YouTube-Kanal: Du kannst dem einen folgen, das andere abonnieren oder beides.`,`Aufgenommen wird, wessen YouTube-Kanal und Mastodon-Konto aufeinander verweisen, wer zuletzt aktiv war und wer unsere Regeln erfüllt: nichts für Erwachsene, nichts Extremistisches.`],kitHeading:(e,o)=>`${e}: ${o} YouTuber auf Mastodon zum Folgen`,kitDescription:(e,o)=>`${o} YouTube-Creator zum Thema ${e}, denen du auf Mastodon folgen kannst \u2013 mit ihren Kan\xE4len. Folgen oder abonnieren in Mawkingbird, ohne YouTube-Konto.`,kitIntro:e=>`YouTube-Creator zum Thema ${e}, die auch auf Mastodon posten. Folge ihren Konten, abonniere ihre Kan\xE4le oder beides \u2013 mit einem Klick in Mawkingbird.`,eyebrow:`YouTuber auf Mastodon`,openKit:`In Mawkingbird folgen und abonnieren`,noAccount:`Noch kein Mastodon-Konto? Die Kanäle kannst du trotzdem abonnieren und die Liste im Browser ausprobieren.`,openApp:`App öffnen`,lastVideo:`Neuestes Video`,videoFeed:`Video-Feed-Konto`,channel:`YouTube-Kanal`,moreKits:`Weitere YouTuber-Listen`,allKits:`Alle YouTuber-Listen`,creators:e=>`${e} Creator`,faqTitle:`Fragen`,faq:[{q:`Brauche ich ein YouTube-Konto?`,a:`Nein. Mawkingbird liest den öffentlichen Feed jedes Kanals, neue Videos erscheinen also in deinen Abos, ohne dass du dich bei YouTube anmeldest.`},{q:`Wer steht hier?`,a:`Creator, deren YouTube-Kanal und Mastodon-Konto aufeinander verweisen – über ihr Profil, ihren Kanal oder Wikidata – und die zuletzt gepostet oder hochgeladen haben. Einige Einträge sind Konten, die die Videos eines Kanals weiterverbreiten; sie sind als Video-Feed-Konten markiert.`},{q:`Wie komme ich auf die Liste oder wieder herunter?`,a:`Die Listen werden regelmäßig aus öffentlichen Profilen erneuert. Wer nicht aufgeführt werden möchte, meldet sich bei Mawkingbird und bleibt bei künftigen Aktualisierungen außen vor.`}],contact:`Mawkingbird auf Mastodon fragen`,alsoIn:`Auch auf`},fr:{hubHeading:`Youtubeurs sur Mastodon : créateurs à suivre, par thème`,hubDescription:`Trouvez les créateurs YouTube présents sur Mastodon, par thème : suivez leurs comptes Mastodon et abonnez-vous à leurs chaînes, sans compte YouTube.`,hubIntro:[`Beaucoup de créateurs YouTube publient aussi sur Mastodon. Ces listes les regroupent par thème, chacun avec son compte Mastodon et sa chaîne YouTube : suivez l’un, abonnez-vous à l’autre, ou les deux.`,`Y figurent les créateurs dont la chaîne YouTube et le compte Mastodon renvoient l’un à l’autre, actifs récemment et conformes à nos règles : rien pour adultes, rien d’extrémiste.`],kitHeading:(e,o)=>`${e} : ${o} youtubeurs \xE0 suivre sur Mastodon`,kitDescription:(e,o)=>`${o} cr\xE9ateurs YouTube (${e}) \xE0 suivre sur Mastodon, avec leurs cha\xEEnes. Suivez-les ou abonnez-vous dans Mawkingbird, sans compte YouTube.`,kitIntro:e=>`Des cr\xE9ateurs YouTube du th\xE8me \xAB ${e} \xBB qui publient aussi sur Mastodon. Suivez leurs comptes, abonnez-vous \xE0 leurs cha\xEEnes, ou les deux, en un clic avec Mawkingbird.`,eyebrow:`Youtubeurs sur Mastodon`,openKit:`Suivre et s’abonner dans Mawkingbird`,noAccount:`Pas encore de compte Mastodon ? Vous pouvez quand même vous abonner aux chaînes et essayer la liste dans votre navigateur.`,openApp:`Ouvrir l’application`,lastVideo:`Dernière vidéo`,videoFeed:`Compte de flux vidéo`,channel:`Chaîne YouTube`,moreKits:`Autres listes de youtubeurs`,allKits:`Toutes les listes de youtubeurs`,creators:e=>`${e} cr\xE9ateurs`,faqTitle:`Questions`,faq:[{q:`Faut-il un compte YouTube ?`,a:`Non. Mawkingbird lit le flux public de chaque chaîne : les nouvelles vidéos apparaissent dans vos abonnements sans connexion à YouTube.`},{q:`Qui figure ici ?`,a:`Des créateurs dont la chaîne YouTube et le compte Mastodon renvoient l’un à l’autre, par leur profil, leur chaîne ou Wikidata, et qui ont publié récemment. Certains comptes republient les vidéos d’une chaîne ; ils sont signalés comme comptes de flux vidéo.`},{q:`Comment être ajouté ou retiré ?`,a:`Les listes sont régulièrement mises à jour à partir des profils publics. Pour ne plus y figurer, contactez Mawkingbird : vous serez exclu des mises à jour suivantes.`}],contact:`Contacter Mawkingbird sur Mastodon`,alsoIn:`Aussi en`},es:{hubHeading:`YouTubers en Mastodon: creadores para seguir, por tema`,hubDescription:`Encuentra creadores de YouTube que están en Mastodon, por tema: sigue sus cuentas de Mastodon y suscríbete a sus canales, sin cuenta de YouTube.`,hubIntro:[`Muchos creadores de YouTube también publican en Mastodon. Estas listas los agrupan por tema, cada uno con su cuenta de Mastodon y su canal de YouTube: sigue una, suscríbete al otro o ambas cosas.`,`Aparecen los creadores cuyo canal de YouTube y cuenta de Mastodon se enlazan entre sí, que han tenido actividad reciente y que cumplen nuestras normas: nada para adultos, nada extremista.`],kitHeading:(e,o)=>`${e}: ${o} YouTubers para seguir en Mastodon`,kitDescription:(e,o)=>`${o} creadores de YouTube de ${e.toLowerCase()} que puedes seguir en Mastodon, con sus canales. S\xEDguelos o suscr\xEDbete en Mawkingbird, sin cuenta de YouTube.`,kitIntro:e=>`Creadores de YouTube de ${e.toLowerCase()} que tambi\xE9n publican en Mastodon. Sigue sus cuentas, suscr\xEDbete a sus canales o ambas cosas, con un clic en Mawkingbird.`,eyebrow:`YouTubers en Mastodon`,openKit:`Seguir y suscribirse en Mawkingbird`,noAccount:`¿Aún no tienes cuenta de Mastodon? Puedes suscribirte a los canales y probar la lista en tu navegador.`,openApp:`Abrir la app`,lastVideo:`Último vídeo`,videoFeed:`Cuenta de vídeos`,channel:`Canal de YouTube`,moreKits:`Más listas de YouTubers`,allKits:`Todas las listas de YouTubers`,creators:e=>`${e} creadores`,faqTitle:`Preguntas`,faq:[{q:`¿Necesito una cuenta de YouTube?`,a:`No. Mawkingbird lee el feed público de cada canal, así que los vídeos nuevos aparecen en tus suscripciones sin iniciar sesión en YouTube.`},{q:`¿Quién aparece aquí?`,a:`Creadores cuyo canal de YouTube y cuenta de Mastodon se enlazan entre sí, por su perfil, su canal o Wikidata, y que han publicado hace poco. Algunas entradas son cuentas que republican los vídeos de un canal; están marcadas como cuentas de vídeos.`},{q:`¿Cómo aparecer o dejar de aparecer?`,a:`Las listas se actualizan con regularidad a partir de perfiles públicos. Si no quieres aparecer, contacta con Mawkingbird y quedarás fuera de las próximas actualizaciones.`}],contact:`Escribir a Mawkingbird en Mastodon`,alsoIn:`También en`},it:{hubHeading:`YouTuber su Mastodon: creator da seguire, per argomento`,hubDescription:`Trova i creator di YouTube presenti su Mastodon, per argomento: segui i loro account Mastodon e iscriviti ai loro canali, senza account YouTube.`,hubIntro:[`Molti creator di YouTube pubblicano anche su Mastodon. Queste liste li raccolgono per argomento, ciascuno con il proprio account Mastodon e il proprio canale YouTube: segui l’uno, iscriviti all’altro, o entrambi.`,`Sono inclusi i creator il cui canale YouTube e account Mastodon rimandano l’uno all’altro, attivi di recente e conformi alle nostre regole: niente contenuti per adulti, niente estremismi.`],kitHeading:(e,o)=>`${e}: ${o} YouTuber da seguire su Mastodon`,kitDescription:(e,o)=>`${o} creator di YouTube (${e}) da seguire su Mastodon, con i loro canali. Seguili o iscriviti in Mawkingbird, senza account YouTube.`,kitIntro:e=>`Creator di YouTube dell\u2019argomento \xAB${e}\xBB che pubblicano anche su Mastodon. Segui i loro account, iscriviti ai loro canali, o entrambi, con un clic in Mawkingbird.`,eyebrow:`YouTuber su Mastodon`,openKit:`Segui e iscriviti in Mawkingbird`,noAccount:`Non hai ancora un account Mastodon? Puoi comunque iscriverti ai canali e provare la lista nel browser.`,openApp:`Apri l’app`,lastVideo:`Ultimo video`,videoFeed:`Account di video`,channel:`Canale YouTube`,moreKits:`Altre liste di YouTuber`,allKits:`Tutte le liste di YouTuber`,creators:e=>`${e} creator`,faqTitle:`Domande`,faq:[{q:`Serve un account YouTube?`,a:`No. Mawkingbird legge il feed pubblico di ogni canale, quindi i nuovi video compaiono nelle tue iscrizioni senza accedere a YouTube.`},{q:`Chi è in elenco?`,a:`Creator il cui canale YouTube e account Mastodon rimandano l’uno all’altro, tramite profilo, canale o Wikidata, e che hanno pubblicato di recente. Alcune voci sono account che ripubblicano i video di un canale; sono indicati come account di video.`},{q:`Come entrare o uscire dall’elenco?`,a:`Le liste si aggiornano regolarmente dai profili pubblici. Per non comparire, contatta Mawkingbird: sarai escluso dagli aggiornamenti successivi.`}],contact:`Scrivere a Mawkingbird su Mastodon`,alsoIn:`Anche in`},nl:{hubHeading:`YouTubers op Mastodon: makers om te volgen, per onderwerp`,hubDescription:`Vind YouTube-makers die op Mastodon zitten, per onderwerp: volg hun Mastodon-accounts en abonneer je op hun kanalen, zonder YouTube-account.`,hubIntro:[`Veel YouTube-makers posten ook op Mastodon. Deze lijsten zetten ze per onderwerp op een rij, elk met hun Mastodon-account en hun YouTube-kanaal: volg het een, abonneer je op het ander, of allebei.`,`Opgenomen zijn makers van wie het YouTube-kanaal en het Mastodon-account naar elkaar verwijzen, die recent actief waren en die aan onze regels voldoen: niets voor volwassenen, niets extremistisch.`],kitHeading:(e,o)=>`${e}: ${o} YouTubers om te volgen op Mastodon`,kitDescription:(e,o)=>`${o} YouTube-makers over ${e.toLowerCase()} die je op Mastodon kunt volgen, met hun kanalen. Volg ze of abonneer je in Mawkingbird, zonder YouTube-account.`,kitIntro:e=>`YouTube-makers over ${e.toLowerCase()} die ook op Mastodon posten. Volg hun accounts, abonneer je op hun kanalen, of allebei, met \xE9\xE9n klik in Mawkingbird.`,eyebrow:`YouTubers op Mastodon`,openKit:`Volgen en abonneren in Mawkingbird`,noAccount:`Nog geen Mastodon-account? Je kunt je toch op de kanalen abonneren en de lijst in je browser proberen.`,openApp:`App openen`,lastVideo:`Nieuwste video`,videoFeed:`Video-feedaccount`,channel:`YouTube-kanaal`,moreKits:`Meer YouTuber-lijsten`,allKits:`Alle YouTuber-lijsten`,creators:e=>`${e} makers`,faqTitle:`Vragen`,faq:[{q:`Heb ik een YouTube-account nodig?`,a:`Nee. Mawkingbird leest de openbare feed van elk kanaal, dus nieuwe video’s verschijnen in je abonnementen zonder bij YouTube in te loggen.`},{q:`Wie staat hier?`,a:`Makers van wie het YouTube-kanaal en het Mastodon-account naar elkaar verwijzen, via hun profiel, hun kanaal of Wikidata, en die onlangs iets hebben gepost of geüpload. Sommige vermeldingen zijn accounts die de video’s van een kanaal doorplaatsen; die staan gemarkeerd als video-feedaccounts.`},{q:`Hoe kom ik erop of eraf?`,a:`De lijsten worden regelmatig ververst uit openbare profielen. Wie er niet op wil staan, neemt contact op met Mawkingbird en wordt bij volgende verversingen overgeslagen.`}],contact:`Mawkingbird op Mastodon vragen`,alsoIn:`Ook in`},ja:{hubHeading:`MastodonにいるYouTuber：テーマ別のおすすめクリエイター`,hubDescription:`MastodonにいるYouTubeクリエイターをテーマ別に紹介。Mastodonアカウントをフォローし、チャンネルを登録できます。YouTubeアカウントは不要です。`,hubIntro:[`多くのYouTubeクリエイターがMastodonにも投稿しています。このリストではテーマ別に、MastodonアカウントとYouTubeチャンネルの両方を紹介しています。フォローだけ、チャンネル登録だけ、または両方も可能です。`,`掲載されるのは、YouTubeチャンネルとMastodonアカウントが互いにリンクしていて、最近活動しており、掲載ルール（アダルトや過激な内容は不可）を満たすクリエイターです。`],kitHeading:(e,o)=>`${e}\uFF1AMastodon\u3067\u30D5\u30A9\u30ED\u30FC\u3067\u304D\u308BYouTuber ${o}\u4EBA`,kitDescription:(e,o)=>`Mastodon\u3067\u30D5\u30A9\u30ED\u30FC\u3067\u304D\u308B\u300C${e}\u300D\u306EYouTube\u30AF\u30EA\u30A8\u30A4\u30BF\u30FC${o}\u4EBA\u3068\u305D\u306E\u30C1\u30E3\u30F3\u30CD\u30EB\u3002Mawkingbird\u306A\u3089YouTube\u30A2\u30AB\u30A6\u30F3\u30C8\u306A\u3057\u3067\u30D5\u30A9\u30ED\u30FC\u3082\u30C1\u30E3\u30F3\u30CD\u30EB\u767B\u9332\u3082\u3067\u304D\u307E\u3059\u3002`,kitIntro:e=>`Mastodon\u306B\u3082\u6295\u7A3F\u3057\u3066\u3044\u308B\u300C${e}\u300D\u306EYouTube\u30AF\u30EA\u30A8\u30A4\u30BF\u30FC\u3002Mawkingbird\u306A\u3089\u3001\u30A2\u30AB\u30A6\u30F3\u30C8\u306E\u30D5\u30A9\u30ED\u30FC\u3001\u30C1\u30E3\u30F3\u30CD\u30EB\u767B\u9332\u3001\u307E\u305F\u306F\u305D\u306E\u4E21\u65B9\u3092\u30EF\u30F3\u30AF\u30EA\u30C3\u30AF\u3067\u3002`,eyebrow:`MastodonにいるYouTuber`,openKit:`Mawkingbirdでフォロー・チャンネル登録`,noAccount:`Mastodonアカウントがなくても、チャンネル登録やブラウザでのお試しができます。`,openApp:`アプリを開く`,lastVideo:`最新動画`,videoFeed:`動画フィードアカウント`,channel:`YouTubeチャンネル`,moreKits:`ほかのYouTuberリスト`,allKits:`すべてのYouTuberリスト`,creators:e=>`${e}\u4EBA`,faqTitle:`よくある質問`,faq:[{q:`YouTubeアカウントは必要ですか？`,a:`いいえ。Mawkingbirdは各チャンネルの公開フィードを読み込むため、YouTubeにログインしなくても新しい動画が登録チャンネルに表示されます。`},{q:`どんな人が掲載されていますか？`,a:`プロフィール、チャンネル、またはWikidataでYouTubeチャンネルとMastodonアカウントが互いにリンクしていて、最近投稿やアップロードをしたクリエイターです。チャンネルの動画を転載するアカウントも一部あり、「動画フィードアカウント」と表示しています。`},{q:`掲載や削除を希望するには？`,a:`リストは公開プロフィールをもとに定期的に更新されます。掲載を望まない場合はMawkingbirdにご連絡ください。以後の更新で除外します。`}],contact:`MastodonでMawkingbirdに問い合わせる`,alsoIn:`ほかの言語`}};function l(e){return c[e]??n}export{d as n,l as r,c as t};